            $(function () {
                $("".add-to-cart"").click(function () {
                    var productid = $('#ProductId').val();
                    var soluong = $('#txtsoluong').val();
                    $.ajax({
                        url: '/api/cart/add',
                        type: ""POST"",
                        dataType: ""JSON"",
                        data: {
                            productID: productid,
                            amount: soluong + 1
                        },
                        success: function (response) {
                            loadHeaderCart();
                            location.reload();
                        },
                        error: function (error) {
                            alert(""There was an error posting the data to the server"" + error.responseText);
                        }
                    });
                });
            });
        });
");
